function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof RANEH_INFO&&(n.innerHTML=RANEH_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderRocks(){const n=document.getElementById("rocks-grid");n&&"undefined"!=typeof GEOLOGY_ROCKS&&(n.innerHTML=GEOLOGY_ROCKS.map(n=>`\n        <div class="rock-card">\n            <span class="color-tag">${n.color}</span>\n            <h3>💎 ${n.name}</h3>\n            <p><strong>Rock Classification:</strong> ${n.type}</p>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderSeasonalData(){const n=document.getElementById("seasonal-grid");n&&"undefined"!=typeof SEASONAL_DATA&&(n.innerHTML=SEASONAL_DATA.map(n=>`\n        <div class="season-card">\n            <h3>🌧️ ${n.season}</h3>\n            <span class="flow-tag">${n.flow}</span>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderAttractions(){const n=document.getElementById("attractions-grid");n&&"undefined"!=typeof NEARBY_ATTRACTIONS&&(n.innerHTML=NEARBY_ATTRACTIONS.map(n=>`\n        <div class="attraction-card">\n            <h3>📍 ${n.name}</h3>\n            <span class="dist-tag">${n.distance} from Raneh</span>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderGallery(){const n=document.getElementById("gallery-grid");n&&"undefined"!=typeof GALLERY_IMAGES&&(n.innerHTML=GALLERY_IMAGES.map(n=>`\n        <div class="gallery-card">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" />\n            <p>${n.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderRocks(),renderSeasonalData(),renderAttractions(),renderGallery(),renderReferences(),initThemeToggle()});